#pragma once
#include <stddef.h>
#include <stdint.h>
#include <ctype.h>
#include <string.h>

// Small allocation-free JSON field scanner used by the real slot HTTP
// handler. It only returns fields at the current object's top level, so text
// inside assembler source cannot masquerade as schema/slot/bank metadata.
template<class S> static bool br_json_string_end(const S &j,size_t start,size_t &end){
  if(start>=j.length()||j[start]!='"')return false;bool escaped=false;
  for(size_t i=start+1;i<j.length();i++){char c=j[i];if(escaped){escaped=false;continue;}if(c=='\\'){escaped=true;continue;}if(c=='"'){end=i+1;return true;}if((uint8_t)c<0x20)return false;}
  return false;
}
template<class S> static bool br_json_top_field_range(const S &j,size_t begin,size_t limit,const char *key,size_t &valueStart){
  const size_t keyLength=strlen(key);unsigned depth=0;if(limit>j.length())limit=j.length();
  for(size_t i=begin;i<limit;i++){char c=j[i];if(c=='"'){size_t end=0;if(!br_json_string_end(j,i,end)||end>limit)return false;size_t next=end;while(next<limit&&isspace((uint8_t)j[next]))next++;if(depth==1&&next<limit&&j[next]==':'&&end-i-2==keyLength){bool same=true;for(size_t k=0;k<keyLength;k++)if(j[i+1+k]!=key[k]){same=false;break;}if(same){valueStart=next+1;while(valueStart<limit&&isspace((uint8_t)j[valueStart]))valueStart++;return true;}}i=end-1;continue;}if(c=='{'||c=='[')depth++;else if(c=='}'||c==']'){if(depth)depth--;}}
  return false;
}
template<class S> static bool br_json_top_field(const S &j,const char *key,size_t &valueStart){return br_json_top_field_range(j,0,j.length(),key,valueStart);}
template<class S> static bool br_json_balanced(const S &j){char stack[32];size_t depth=0;bool inString=false,escaped=false;for(size_t i=0;i<j.length();i++){char c=j[i];if(inString){if(escaped){escaped=false;continue;}if(c=='\\'){escaped=true;continue;}if(c=='"')inString=false;else if((uint8_t)c<0x20)return false;continue;}if(c=='"'){inString=true;continue;}if(c=='{'||c=='['){if(depth==sizeof(stack))return false;stack[depth++]=c;}else if(c=='}'||c==']'){if(!depth||((c=='}')!=(stack[depth-1]=='{')))return false;--depth;}}return !inString&&!escaped&&depth==0;}
template<class S> static bool br_json_object_range(const S &j,const char *key,size_t &start,size_t &end){if(!br_json_top_field(j,key,start)||start>=j.length()||j[start]!='{')return false;unsigned depth=0;bool inString=false,escaped=false;for(size_t i=start;i<j.length();i++){char c=j[i];if(inString){if(escaped)escaped=false;else if(c=='\\')escaped=true;else if(c=='"')inString=false;continue;}if(c=='"'){inString=true;continue;}if(c=='{')depth++;else if(c=='}'&&--depth==0){end=i+1;return true;}}return false;}
template<class S> static bool br_json_unsigned(const S &j,const char *key,uint32_t &value){size_t p=0;if(!br_json_top_field(j,key,p)||p>=j.length()||!isdigit((uint8_t)j[p]))return false;uint64_t n=0;while(p<j.length()&&isdigit((uint8_t)j[p])){n=n*10+(j[p++]-'0');if(n>0xffffffffu)return false;}if(p<j.length()&&!isspace((uint8_t)j[p])&&j[p]!=','&&j[p]!='}'&&j[p]!=']')return false;value=(uint32_t)n;return true;}
template<class S> static bool br_json_boolean(const S &j,const char *key,bool &value){size_t p=0;if(!br_json_top_field(j,key,p))return false;if(p+4<=j.length()&&j[p]=='t'&&j[p+1]=='r'&&j[p+2]=='u'&&j[p+3]=='e'){value=true;return p+4==j.length()||isspace((uint8_t)j[p+4])||j[p+4]==','||j[p+4]=='}';}if(p+5<=j.length()&&j[p]=='f'&&j[p+1]=='a'&&j[p+2]=='l'&&j[p+3]=='s'&&j[p+4]=='e'){value=false;return p+5==j.length()||isspace((uint8_t)j[p+5])||j[p+5]==','||j[p+5]=='}';}return false;}
template<class S> static void br_json_append_utf8(S &out,uint32_t code){if(code<=0x7f)out+=(char)code;else if(code<=0x7ff){out+=(char)(0xc0|(code>>6));out+=(char)(0x80|(code&0x3f));}else if(code<=0xffff){out+=(char)(0xe0|(code>>12));out+=(char)(0x80|((code>>6)&0x3f));out+=(char)(0x80|(code&0x3f));}else{out+=(char)(0xf0|(code>>18));out+=(char)(0x80|((code>>12)&0x3f));out+=(char)(0x80|((code>>6)&0x3f));out+=(char)(0x80|(code&0x3f));}}
template<class S> static bool br_json_string_at(const S &j,size_t p,size_t limit,S &out,bool &isNull){if(limit>j.length())limit=j.length();if(p>=limit)return false;isNull=false;if(p+4<=limit&&j[p]=='n'&&j[p+1]=='u'&&j[p+2]=='l'&&j[p+3]=='l'){isNull=true;out=S();return true;}if(j[p]!='"')return false;out=S();for(size_t i=p+1;i<limit;i++){char c=j[i];if(c=='"')return true;if(c!='\\'){if((uint8_t)c<0x20)return false;out+=c;continue;}if(++i>=limit)return false;c=j[i];switch(c){case '"':case '\\':case '/':out+=c;break;case 'n':out+='\n';break;case 'r':out+='\r';break;case 't':out+='\t';break;case 'b':out+='\b';break;case 'f':out+='\f';break;case 'u':{if(i+4>=limit)return false;uint32_t code=0;for(unsigned k=1;k<=4;k++){char h=j[i+k];int d=h>='0'&&h<='9'?h-'0':h>='A'&&h<='F'?h-'A'+10:h>='a'&&h<='f'?h-'a'+10:-1;if(d<0)return false;code=(code<<4)|(uint32_t)d;}i+=4;if(code>=0xd800&&code<=0xdbff){if(i+6>=limit||j[i+1]!='\\'||j[i+2]!='u')return false;uint32_t low=0;for(unsigned k=3;k<=6;k++){char h=j[i+k];int d=h>='0'&&h<='9'?h-'0':h>='A'&&h<='F'?h-'A'+10:h>='a'&&h<='f'?h-'a'+10:-1;if(d<0)return false;low=(low<<4)|(uint32_t)d;}if(low<0xdc00||low>0xdfff)return false;code=0x10000+((code-0xd800)<<10)+(low-0xdc00);i+=6;}if(code>=0xdc00&&code<=0xdfff)return false;br_json_append_utf8(out,code);break;}default:return false;}}return false;}
template<class S> static bool br_json_string_range(const S &j,size_t begin,size_t limit,const char *key,S &out,bool &isNull){size_t p=0;return br_json_top_field_range(j,begin,limit,key,p)&&br_json_string_at(j,p,limit,out,isNull);}
template<class S> static bool br_json_string(const S &j,const char *key,S &out,bool &isNull){size_t p=0;return br_json_top_field(j,key,p)&&br_json_string_at(j,p,j.length(),out,isNull);}
